def kern_to_music_xml(kernfile, outfile):
    score = converter.parse(kernfile)
    score.write("musicxml", fp=outfile)


def musicxml_to_pdf(mxlfile, pdf_outpath):
    with open(os.devnull, "w") as devnull:
        subprocess.run(["bin/mscore-wrapper", "-o", "bin/output.mscx", mxlfile], stdout=devnull, stderr=devnull)
        subprocess.run(["bin/mscore-wrapper", "-o", pdf_outpath, "bin/output.mscx"], stdout=devnull, stderr=devnull)


