def create_diff_pdf(gt_krnfile, gt_pdf_outpath):
    hyp_krnfile = gt_krnfile.replace("gt", "hyp")
    hyp_pdf_outpath = gt_pdf_outpath.replace("gt", "hyp")

    hyp_mxlfile = hyp_krnfile.split(".")
    hyp_mxlfile[-1] = "musicxml"
    hyp_mxlfile = ".".join(hyp_mxlfile)

    gt_mxlfile = gt_krnfile.split(".")
    gt_mxlfile[-1] = "musicxml"
    gt_mxlfile = ".".join(gt_mxlfile)

    kern_to_music_xml(gt_krnfile, gt_mxlfile)
    musicxml_to_pdf(gt_mxlfile, gt_pdf_outpath)

    try:
        result = diff(
            score1=gt_krnfile,
            score2=hyp_krnfile,
            out_path1="/tmp/output",
            out_path2=hyp_mxlfile,
        )
        if result == 0:
            kern_to_music_xml(hyp_krnfile, hyp_mxlfile)
        musicxml_to_pdf(hyp_mxlfile, hyp_pdf_outpath)

    except HumdrumException:
        pass
    except MusicXMLExportException:
        pass


def create_diff_pdfs(base_filepath, d="val", krn_filter=None):
    gt_dir = f"{base_filepath}/gt/{d}"

    gt_krnfiles = glob.glob(gt_dir + "/**/*.krn", recursive=True)
    if krn_filter is not None:
        gt_krnfiles = list(filter(lambda x: any(f"/{y}.krn" in x for y in krn_filter), gt_krnfiles))

    gt_krnfiles = tqdm(gt_krnfiles, desc=f"running diff of hyp and gt for {gt_dir}")

    for gt_krnfile in gt_krnfiles:
        gt_pdf_outpath = gt_krnfile.split(".")
        gt_pdf_outpath[-1] = "pdf"
        gt_pdf_outpath = ".".join(gt_pdf_outpath)

        create_diff_pdf(gt_krnfile, gt_pdf_outpath)


